import React, { useState, useRef, useEffect } from "react";
import styled, { keyframes } from "styled-components";

import fetchQuery from "../components/fetchQuery";
import PageWrapper from "../components/PageWrapper";
import BookCard from "../components/BookCard";
import CardButton from "../components/CardButton";
import BookGrid from "../components/BookGrid";

import withLoadingAnimation from "../components/hoc/withLoadingAnimation";
import withImageLoading from "../components/hoc/withImageLoading";

const shine = keyframes`
  0% { background-position: -200px 0; }
  100% { background-position: 200px 0; }
`;

const Container = styled.div`
  margin: 40px auto;
  max-width: 1400px;
  font-family: "Poppins", sans-serif;
  display: flex;
  flex-direction: column;
  gap: 30px;
`;

const Heading = styled.h2`
  font-size: 3rem;
  font-weight: 800;
  background: linear-gradient(90deg, #ff416c, #ff4b2b, #ffe259);
  background-size: 200% auto;
  color: transparent;
  -webkit-background-clip: text;
  background-clip: text;
  animation: ${shine} 3s linear infinite;
  text-align: center;
`;

const SearchWrapper = styled.form`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 15px;
  justify-content: center;
  margin-bottom: 20px;
`;

const DropDownWrapper = styled.div`
  position: relative;
`;

const DropDownButton = styled.button`
  padding: 10px 18px;
  background: #1f1f1f;
  color: white;
  border: none;
  border-radius: 12px;
  font-size: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 5px;
  transition: all 0.3s ease;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);

  &:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.4);
  }
`;

const DropDownContent = styled.div`
  position: absolute;
  top: 45px;
  left: 0;
  background: #1f1f1f;
  color: #fff;
  border-radius: 10px;
  width: 180px;
  z-index: 10;
  display: ${(props) => (props.open ? "block" : "none")};
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.35);
  overflow: hidden;
`;

const DropDownItem = styled.div`
  padding: 10px 12px;
  cursor: pointer;
  transition: all 0.2s ease;

  &:hover {
    background-color: #ff416c;
    color: #fff;
  }
`;

const Input = styled.input`
  padding: 12px 16px;
  font-size: 16px;
  border: none;
  border-radius: 12px;
  width: 220px;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.15);
  transition: all 0.3s ease;

  &:focus {
    outline: none;
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.25);
  }
`;

const InputWrapper = styled.div`
  position: relative;
`;


const SuggestionBox = styled.div`
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  width: 100%;
  background: #1f1f1f;
  border-radius: 12px;
  z-index: 20;
  max-height: 280px;
  overflow-y: auto;
`;

const SuggestionItem = styled.div`
  padding: 10px 14px;
  cursor: pointer;
  color: #fff;

  &:hover {
    background: #ff416c;
  }
`;

const Backdrop = styled.div`
  position: fixed;
  top: 70px;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  z-index: 99;
`;

const SidePanel = styled.div`
  position: fixed;
  top: 70px;
  right: 0;
  width: 420px;
  max-width: 90vw;
  height: 100vh;
  background: ${({ theme }) =>
    theme?.mode === "dark" ? "#121212" : "#ffffff"};
  box-shadow: -10px 0 30px rgba(0, 0, 0, 0.35);
  padding: 24px;
  z-index: 100;
  overflow-y: auto;
  animation: slideIn 0.3s ease forwards;

  @keyframes slideIn {
    from {
      transform: translateX(100%);
    }
    to {
      transform: translateX(0);
    }
  }
`;

const CloseButton = styled.button`
  background: none;
  border: none;
  font-size: 28px;
  cursor: pointer;
  color: #ff416c;
  position: absolute;
  top: 15px;
  right: 20px;
`;

const Button = styled.button`
  padding: 12px 22px;
  background: linear-gradient(135deg, #ff416c, #ff4b2b);
  color: #fff;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  font-size: 16px;
  font-weight: 600;
  box-shadow: 0 6px 20px rgba(255, 65, 108, 0.5);
  transition: all 0.3s ease;

  &:hover {
    transform: translateY(-2px);
    box-shadow: 0 12px 30px rgba(255, 65, 108, 0.6);
  }
`;

const ButtonWrapper = styled.div`
  margin-top: 8px;
  display: flex;
  justify-content: center;
`;

const PagePagination = styled.div`
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 20px;
`;

const PaginationButton = styled(Button)`
  padding: 8px 14px;
  border-radius: 50%;
  font-weight: bold;

  &:disabled {
    opacity: 0.4;
    cursor: default;
    transform: none;
    box-shadow: none;
  }
`;

const AddBook = () => {
  const [criteria, setCriteria] = useState("Title");
  const [inputValue, setInputValue] = useState("");
  const [sort, setSort] = useState("Relevance");
  const [books, setBooks] = useState([]);
  const [searchDropDownOpen, setSearchDropDownOpen] = useState(false);
  const [sortDropDownOpen, setSortDropDownOpen] = useState(false);
  const [suggestions, setSuggestions] = useState([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const typingTimeout = useRef(null);
  const [page, setPage] = useState(1);
  const [addedBooks, setAddedBooks] = useState({});
  const [loading, setLoading] = useState(false);
  const [selectedBook, setSelectedBook] = useState(null);
  useEffect(() => {
  return () => {
    if (typingTimeout.current) clearTimeout(typingTimeout.current);
    };
  }, []);
  useEffect(() => {
  document.body.style.overflow = selectedBook ? "hidden" : "auto";
  }, [selectedBook]);

  const pageSize = 24;
  const totalPages = Math.ceil(books.length / pageSize);

  const handleSearch = async (e) => {
    e?.preventDefault();
    if (!inputValue.trim()) return;
    setBooks([]);
    setLoading(true);
    const result = await fetchQuery(null, criteria, inputValue, sort);
    setShowSuggestions(false);
    setSuggestions([]);
    setBooks(result || []);
    setPage(1);
    setLoading(false);
  };

  const addtoLib = (book) => {
    if (addedBooks[book.title]) return;
    setAddedBooks((prev) => ({ ...prev, [book.title]: true }));
    let myBooks = JSON.parse(localStorage.getItem("books")) || {};
    myBooks[book.title] = book;
    localStorage.setItem("books", JSON.stringify(myBooks));
  };

  const toggleSearchDropDown = () => {
    setSearchDropDownOpen(!searchDropDownOpen);
    setSortDropDownOpen(false);
  };
  const toggleSortDropDown = () => {
    setSortDropDownOpen(!sortDropDownOpen);
    setSearchDropDownOpen(false);
  };
  const handleSearchDropDownItemClick = (newCriteria) => {
    setCriteria(newCriteria);
    setSearchDropDownOpen(false);
  };
  const handleSortDropDownItemClick = (newSort) => {
    setSort(newSort);
    setSortDropDownOpen(false);
  };

const fetchSuggestions = async (criteria, value) => {
  const res = await fetchQuery(null, criteria, value, "Relevance");
  return res?.slice(0, 6) || [];
};

const lastRequestId = useRef(0);

const handleLiveSearch = async (value) => {
  if (!value.trim()) {
    setSuggestions([]);
    setShowSuggestions(false);
    return;
  }

  const requestId = ++lastRequestId.current;

  const result = await fetchSuggestions(criteria, value);

  if (requestId !== lastRequestId.current) return;
  setSuggestions(result);
  setShowSuggestions(true);
};

  const BookCardWithImageLoading = (props) => {
    const ImageWithLoading = withImageLoading(({ src, alt }) => (
      <img src={src} alt={alt} style={{ width: "100%", height: "auto" }} />
    ));
    return <BookCard {...props} ImageComponent={ImageWithLoading} />;
  };

  const BookGridWithLoading = withLoadingAnimation(BookGrid);

  return (
    <PageWrapper>
      <Container>
        <Heading>Discover Your Next Favorite Book</Heading>

        <SearchWrapper onSubmit={handleSearch}>
          <DropDownWrapper>
            <DropDownButton type="button" onClick={toggleSearchDropDown}>
              Search By: {criteria}
            </DropDownButton>
            <DropDownContent type="button" open={searchDropDownOpen}>
              {["Title", "Author", "ISBN"].map((item) => (
                <DropDownItem type="button"key={item} onClick={() => handleSearchDropDownItemClick(item)}>
                  {item}
                </DropDownItem>
              ))}
            </DropDownContent>
          </DropDownWrapper>

          <DropDownWrapper>
            <DropDownButton type="button" onClick={toggleSortDropDown}>
              Sort By: {sort}
            </DropDownButton>
            <DropDownContent type="button" open={sortDropDownOpen}>
              {["Relevance", "Newest", "Rating"].map((item) => (
                <DropDownItem type="button" key={item} onClick={() => handleSortDropDownItemClick(item)}>
                  {item}
                </DropDownItem>
              ))}
            </DropDownContent>
          </DropDownWrapper>

          <InputWrapper><Input
            type="text"
            value={inputValue}
            onChange={(e) => {
              const value = e.target.value;
              setInputValue(value);

              if (typingTimeout.current) {
                clearTimeout(typingTimeout.current);
              }
              typingTimeout.current = setTimeout(() => {
                handleLiveSearch(value);
              }, 500);
        }}
  onFocus={() => suggestions.length && setShowSuggestions(true)}
  placeholder={`Enter ${criteria}`}
  onBlur={() => setTimeout(() => setShowSuggestions(false), 150)}
/>
          {showSuggestions && suggestions.length > 0 && (
                          <SuggestionBox>
                {suggestions.map((book) => (
                  <SuggestionItem
                    key={book.isbn}
                    onClick={() => {
                      setInputValue(book.title);
                      setShowSuggestions(false);
                      handleSearch();
            }}
          >
          {book.title}
          </SuggestionItem>
                ))}
              </SuggestionBox>
            )}
          </InputWrapper>


          <Button type="submit">Search</Button>
        </SearchWrapper>

        <BookGridWithLoading loading={loading} >
          {books.length > 0 &&
            books.slice((page - 1) * pageSize, page * pageSize).map((book) => (
              <div key={book.isbn}>
                <BookCardWithImageLoading {...book} onClick={() => setSelectedBook(book)} />
                <ButtonWrapper>
                  <CardButton
                    type="button"
                    variant="add"
                    onClick={() => addtoLib(book)}
                  >
                    {addedBooks[book.title] ? "Added! Enjoy Reading!" : "Add to Library"}
                  </CardButton>

                </ButtonWrapper>
              </div>
            ))}
        </BookGridWithLoading>
    {selectedBook && (
    <div >
    <Backdrop onClick={() => setSelectedBook(null)} />
    <SidePanel>
      <CloseButton onClick={() => setSelectedBook(null)}>×</CloseButton>

    <img
      src={selectedBook.thumbnail}
      alt={selectedBook.title}
      style={{ width: "100%", borderRadius: "12px", marginBottom: "20px" }}
    />

    <h2>{selectedBook.title}</h2>
    <p><strong>Author:</strong> {selectedBook.author}</p>
    <p><strong>Rating:</strong> ⭐ {selectedBook.rating || "N/A"}</p>

    <p style={{ marginTop: "15px", lineHeight: "1.6" }}>
      {selectedBook.description || "No description available."}
    </p>

    <Button
      style={{ marginTop: "20px", width: "100%" }}
      onClick={() => addtoLib(selectedBook)}
    >
      {addedBooks[selectedBook.title]
        ? "Added to Library"
        : "Add to Library"
      }
    </Button>
    </SidePanel>
    </div>
    )}


        {books.length > 0 && totalPages > 1 && (
          <PagePagination>
            {page > 1 && ( 
              <PaginationButton type="button" onClick={() => setPage(page - 1)}>{"<"}</PaginationButton>
            )}
            {Array.from({ length: totalPages }, (_, index) => (
              <PaginationButton
                key={index}
                onClick={() => setPage(index + 1)}
                disabled={page === index + 1}
              >
                {index + 1}
              </PaginationButton>
            ))}
            {page < totalPages && (
              <PaginationButton type="button"onClick={() => setPage(page + 1)}>{">"}</PaginationButton>
            )}
          </PagePagination>
        )}
      </Container>
    </PageWrapper>
  )};

export default AddBook;
